mapper.select:
SELECT 

FROM TBL_CREDIT_CONTRACT cc
LEFT JOIN TBL_COMPANY c ON cc.COMPANY_ID = c.ID
LEFT JOIN TBL_FINANCING_INSTITUTION fi ON cc.FINANCING_INSTITUTION_ID = fi.ID
LEFT JOIN TBL_USER cu ON cc.CREATEUSER = cu.ID
LEFT JOIN TBL_USER uu ON cc.UPDATEUSER = uu.ID


        AND cc.CONTRACT_NO LIKE '%' || #{contractNo} || '%'


        AND c.COMPANY_NAME LIKE '%' || #{companyName} || '%'


        AND cc.CREDIT_TYPE = #{creditType}


        AND cc.CONTRACT_STATUS = #{contractStatus}


        AND fi.INSTITUTION_NAME LIKE '%' || #{financingInstitution} || '%'


        AND cc.CONTRACT_START_DATE >= #{startDate}


        AND cc.CONTRACT_END_DATE <= #{endDate}


        AND cc.ORGID = #{orgId}


ORDER BY cc.CREATETIME DESC

mapper.update:
UPDATE TBL_CREDIT_CONTRACT
CONTRACT_NO = #{contractNo}, APPLICATION_ID = #{applicationId}, COMPANY_ID = #{companyId}, FINANCING_INSTITUTION_ID = #{financingInstitutionId}, CREDIT_TYPE = #{creditType}, CREDIT_AMOUNT = #{creditAmount}, CURRENCY_CODE = #{currencyCode}, CREDIT_TERM = #{creditTerm}, CONTRACT_START_DATE = #{contractStartDate}, CONTRACT_END_DATE = #{contractEndDate}, GUARANTEE_METHOD = #{guaranteeMethod}, GUARANTEE_DETAILS = #{guaranteeDetails}, INTEREST_RATE_TYPE = #{interestRateType}, BASE_RATE = #{baseRate}, RATE_SPREAD = #{rateSpread}, COMMITMENT_FEE_RATE = #{commitmentFeeRate}, MANAGEMENT_FEE_RATE = #{managementFeeRate}, SPECIAL_CLAUSES = #{specialClauses}, DEFAULT_CLAUSES = #{defaultClauses}, CONTRACT_STATUS = #{contractStatus}, CONTRACT_FILE_PATH = #{contractFilePath}, SIGN_DATE = #{signDate}, SIGN_USER = #{signUser}, TERMINATE_REASON = #{terminateReason}, TERMINATE_DATE = #{terminateDate}, UPDATETIME = #{updateTime}, UPDATEUSER = #{updateUser}, REMARK = #{remark},
WHERE ID = #{id}

