SELECT COUNT(*) FROM TBL_CREDIT_CONTRACT
WHERE CONTRACT_STATUS = #{status}

    AND ORGID = #{orgId}

SELECT COUNT(*) FROM TBL_CREDIT_CONTRACT
WHERE CONTRACT_STATUS = 'EFFECTIVE'
AND CONTRACT_END_DATE BETWEEN SYSDATE AND SYSDATE + #{days}

    AND ORGID = #{orgId}

SELECT CURRENCY_CODE, SUM(CREDIT_AMOUNT) AS TOTAL_AMOUNT, COUNT(*) AS CONTRACT_COUNT FROM TBL_CREDIT_CONTRACT WHERE CONTRACT_STATUS = 'EFFECTIVE'
AND ORGID = #{orgId}
GROUP BY CURRENCY_CODE

SELECT
FROM TBL_CREDIT_CONTRACT cc LEFT JOIN TBL_COMPANY c ON cc.COMPANY_ID = c.ID LEFT JOIN TBL_FINANCING_INSTITUTION fi ON cc.FINANCING_INSTITUTION_ID = fi.ID LEFT JOIN TBL_USER cu ON cc.CREATEUSER = cu.ID LEFT JOIN TBL_USER uu ON cc.UPDATEUSER = uu.ID WHERE cc.CONTRACT_STATUS = 'EFFECTIVE' AND cc.CONTRACT_END_DATE BETWEEN SYSDATE AND SYSDATE + #{days}
AND cc.ORGID = #{orgId}
ORDER BY cc.CONTRACT_END_DATE ASC

SELECT COUNT(*) FROM TBL_CREDIT_CONTRACT
WHERE CONTRACT_NO = #{contractNo}

    AND ID != #{excludeId}
